rows=[]
def event(year,title,place,people,topic,background,development,impact,evidence,sources,end=None):
 rows.append(dict(id=f'cn-{year:04d}-{len(rows)+1:02d}',year=year,endYear=end or year,title=title,place=place,people=people.split('、'),topic=topic,summary=development,sections=[dict(title='背景与处境',text=background),dict(title='事件经过',text=development),dict(title='影响与比较线索',text=impact),dict(title='史料与年代提示',text=evidence)],sourceIds=sources.split(',')))
event(36,'东汉结束主要统一战争','成都、洛阳','刘秀、吴汉、公孙述','政治与制度','新莽覆亡以后，刘秀建立东汉，但各地军事集团并未立即归附。洛阳的中央政权需要逐步取得财政、人口和地方官僚的支持。','吴汉等攻破公孙述控制的成都，东汉结束主要的统一战争。应将25年称帝、36年统一进程和此后的治理恢复分开理解。','与使徒时代并置时，可观察统一政治秩序如何维持交通、征税和城市生活；这只是制度环境的比较，并不构成东汉与教会已有接触的证据。','依《后汉书》建武十二年纪事整理。“统一”指主要割据势力的覆亡，不表示所有边疆冲突或地方问题同时终止。','han1')
event(57,'光武帝去世与明帝继位','洛阳','刘秀、刘庄','政治与制度','光武帝长期统治形成了东汉前期的中央权力结构。皇位传承仍需借助宗室、官僚和礼仪制度来维持连续性。','光武帝去世，太子刘庄继位，是为汉明帝。地图上朝代仍为东汉，统治者和政治议题却已变化。','这一节点提醒读者：朝代名称不变，不等于社会和政策保持静止。对照保罗晚期旅程时，应分别标出两边具体人物与实际年代。','本条为公历年层面的政治节点，不把后世“明帝梦佛”的传说当作57年已经发生的确定事件。','han1,han2')
event(65,'楚王英与黄老、浮屠记述','楚国、洛阳','刘英、汉明帝','宗教与思想','东汉宗室、地方社会与不同祭祀实践之间存在多种关系。关于宗教活动的记录往往由后来的官修史书保存。','《后汉书》楚王英传保存永平八年诏书，涉及黄老及浮屠等表述，可用来讨论早期佛教在中国的文字可见性。','这份材料与基督徒书信、使徒行传属于不同传统。不能因两者同时出现，就将“浮屠”改称基督徒，或把楚王英归为早期中国基督徒。','诏书由后世史书传录；术语、传播范围与实际社群规模都需要谨慎解释。这里不采用“此年佛教才第一次传入”的单点叙事。','han42')
event(73,'班超在西域的活动展开','鄯善、于阗及西域诸地','班超','交通与交流','东汉对西域的经营牵涉军事、外交、绿洲政权与道路安全。所谓丝绸之路由多条不同时期变化的路线组成。','班超出使并开展西域活动，逐步建立与多个绿洲政权的关系。这是一个持续多年的过程，不是一趟完成全部目标的旅行。','这些网络有助于理解欧亚交流的基础条件，但道路能够相通，与某个宗教已经沿路抵达某地，是两种不同的证据判断。','73年用作活动展开的节点；后续任职、战事和回国另有年代，不能全部压缩进同一年。','han47')
event(97,'甘英出使大秦而未抵达','西域至条支一带','甘英、班超','交通与交流','东汉借助西域的政治关系，尝试了解更西方的地区。古籍中的地名及其现代对应常有争论。','班超派甘英出使大秦。依《后汉书》记述，甘英到达海边后因航行条件等信息而没有继续前往大秦。','这是一条具体的远行记录，仍不能写成汉使已到罗马、见到保罗或与罗马教会接触。政治地理想象与实际到达地点应分开。','“条支”“海”的位置有不同研究方案；本项目不据此绘制一条精确到现代城市的确定航线。','han47')
event(105,'蔡伦上奏造纸成果','洛阳','蔡伦','文本与科技','汉代已有多种书写材料，纸的形成与改进也有较长过程。帝国行政及知识保存对材料的成本、运输和耐用性有持续需求。','《后汉书》记蔡伦利用树皮、麻头等材料造纸，并在元兴元年上奏。这个节点代表史书所记的一次改进与推广。','与地中海的纸草、羊皮和书信文化比较，可以讨论材料如何影响文本复制；不能把材料变化直接等同于阅读普及，更不能称105年才首次出现纸。','传记成书晚于蔡伦；考古发现与史书记功关注的问题不同。此条不主张蔡伦是唯一的、从零开始的纸的发明者。','han78')
event(184,'黄巾起事与地方军事力量','冀州及多地','张角、皇甫嵩、朱儁','政治与制度','东汉末年的政治冲突、地方社会压力与宗教性组织相互交织。中央和地方并非具有完全一致的资源与行动能力。','张角等组织的黄巾起事爆发，朝廷动员官军镇压。起事受挫后，地方军事集团及相关社会动员仍持续影响汉末局势。','可与罗马帝国中的宗教群体比较组织、救助和权威，但太平道的信仰、行动方式与基督教社群不能因同时期而混同。','以中平元年为节点；不是所有汉末战争都由黄巾直接造成，也不能将一个组织概括成所有普通民众的立场。','han71')
event(200,'官渡之战与北方局势','官渡、许都','曹操、袁绍','战争与迁徙','汉廷权威衰弱后，不同军事集团争夺人口、土地与朝廷名义。战争供给同样影响战局。','曹操与袁绍在官渡交战，曹操获胜。此后北方权力格局继续经过多次战役调整，并非在200年即完全统一。','比较军事权力时，也可追问战争如何改变农业、迁徙和普通人的生活。人物能力只是解释的一部分，粮运与政治联盟同样重要。','依据建安五年编年；《三国志》正文、裴注与后来的小说叙事应分别辨认。','wei1')
event(208,'赤壁之战与南北分立','长江中游','曹操、孙权、刘备、周瑜','战争与迁徙','曹操南下面对长江流域的既有势力。南北战争环境、航行条件与联盟关系共同影响军事选择。','孙刘联盟与曹军交战，曹操退兵。此后刘备、孙权等的扩展，逐渐形成魏蜀吴分立的政治基础。','这一节点适合结合江河地理理解战争，却不能把赤壁直接标成“三国在此年建国”。三政权正式建立各有自己的时间。','战场具体位置、兵力与部分细节存在研究分歧；不用《三国演义》的情节填补史料空缺。','wei1')
event(220,'曹丕代汉建立魏','洛阳、许都','曹丕、汉献帝','政治与制度','曹操控制汉廷多年，但生前并未称帝。继承者曹丕面对的是如何把实际军事政治权力转为新王朝的合法地位。','曹丕接受汉献帝禅让，建立魏，东汉结束。刘备与孙权的政权建号另有年代，不应全部记作220年同时建国。','禅让文书与礼仪展现了权力如何解释自身。与罗马皇帝继位或教会权威比较时，应保留各自制度语境。','《三国志》称曹操为太祖属于后来的追尊，不等于他生前已是皇帝。此处区别追尊、实际继位与政权建立。','wei2')
event(265,'司马炎建立西晋','洛阳','司马炎、曹奂','政治与制度','司马氏在魏政权内部逐步取得主导权。王朝更替仍通过皇帝、官僚与礼仪结构表达。','司马炎代魏建立晋，史称西晋。蜀汉此前已亡，东吴仍存在，因此265年不能称为全国统一完成之年。','地图应该同时呈现晋与吴，而不是因新朝建立就提前抹除其他政权。政治分期与实际控制范围需要分别检查。','泰始元年对应265年；统一节点另见280年。史书的王朝正统叙述不等于所有地方同时接受新制度。','jin3')
event(280,'西晋灭吴与阶段统一','建业、洛阳','司马炎、孙皓','政治与制度','西晋完成对东吴的军事部署，长江防线和多路进军构成战役背景。吴的地方制度与社会关系并未因战败立即消失。','晋军攻入建业，孙皓投降，三国时期的分立结束，西晋实现阶段性统一。','与三世纪罗马帝国比较，可讨论军事整合之后的治理成本；统一是一个政治结果，不自动意味着地方社会安定或宗教一致。','以太康元年为节点。将此年和265年建晋区分，也不把后来的西晋崩解倒写成所有政策一开始必然失败。','jin3')
event(311,'洛阳陷落与永嘉之乱','洛阳及北方诸地','晋怀帝、刘聪','战争与迁徙','八王之乱和北方军事集团的兴起，使西晋朝廷与地方秩序日益脆弱。战争、饥荒和迁徙的影响因地区而异。','汉赵军攻陷洛阳，晋怀帝被俘。此事是西晋瓦解中的重大节点，但长安政权及各地势力仍继续活动。','与四世纪初罗马对基督徒的政策变化并置时，重点是不同处境下的组织重建与迁徙，不能把两边讲成同一场帝国转折。','“永嘉之乱”也可指较长时段的动荡；本条选311年洛阳陷落，不以一个日期替代全部人口移动。','jin5')
event(317,'东晋政权在建康形成','建康、江南','司马睿、王导','政治与制度','北方战事使晋宗室、官僚与人口持续南移；江南原有地方家族和北来士族共同参与权力重组。','司马睿在建康称晋王，东晋政权形成；次年称帝。建康成为此后南方政治与文化的重要中心。','南迁不是空地上建立新国家。移民、地方居民与精英合作冲突的关系，能补充只看疆域图所遗漏的社会历史。','317年称王与318年称帝分开标注；“东晋建立”常以317年为分期节点，不能把两项礼仪写成同日。','jin6')
event(353,'兰亭雅集与士人交往','会稽山阴、兰亭','王羲之、孙绰、谢安','宗教与思想','东晋士人借家族、官职、清谈与诗文建立交往网络。书法作品的传播又与后世摹写、收藏和鉴赏有关。','王羲之等在兰亭聚会，留下诗文及著名的序文传统。文本展示了友谊、山水经验和对生命有限性的思考。','可与教会书信和修道社群比较文本如何维持关系，但不应把雅集解释为教会聚会。相似的交往形式并不意味着同一信仰内容。','兰亭序原迹不存；现存摹本、刻帖和后世论述具有不同的年代与真实性问题。王羲之生卒年也有不同研究意见。','wang')
event(383,'淝水之战与前秦南进受挫','淝水、寿阳','苻坚、谢安、谢玄','战争与迁徙','前秦整合北方后大举南进，东晋内部也存在不同政治军事力量。动员规模不等于实际战场中可用的兵力。','东晋军在淝水击败前秦军，苻坚南进受挫，前秦统治随后发生危机。南北分立继续，但北方仍有新的整合过程。','可以通过河流、补给、联盟和统治整合分析战局，不只依赖人物逸事。南北分立也不意味着贸易、人口和文本完全断绝。','古代记载的兵力和名言需审慎使用；本项目不把戏剧化故事当作经过逐项验证的战斗记录。','jin8')
event(399,'法显西行求律','长安至中亚、南亚','法显、同行僧人','交通与交流','中国佛教的发展需要不同戒律与经典文本。求学、译经和远行由具体僧侣、施主及沿途社群共同支持。','法显从长安出发西行，经过中亚进入南亚，寻求戒律等文本；之后经海路返回。此条以出发年作为长途过程的起点。','这是真实的佛教旅行传统，可以帮助比较跨区域宗教网络。不能把法显沿途所见一律称为基督教社群或统一的“西方文明”。','《佛国记》含旅行叙述及成书层次；个别地名与路线需专门历史地理考证。未将整段旅程标成单年完成。','faxian',414)
event(420,'刘裕建宋与南朝分期','建康','刘裕、晋恭帝','政治与制度','东晋末年的军事整合改变了南方权力结构。建康的行政、士族网络及地方社会仍有延续。','刘裕代晋建立宋，史称刘宋，南朝分期由此展开。这里的宋不同于960年赵匡胤建立的宋。','同名王朝是对照阅读的常见混淆。地图与人物条目应标明年代、政权及地域，避免把刘宋与宋代理学、城市文化连在一起。','420年为政权建立节点；南北朝是后世概括的历史分期，不是当时所有人共同使用的单一国家名称。','song')
event(494,'北魏迁都与制度文化调整','平城、洛阳','北魏孝文帝','政治与制度','北魏统治北方多种居民群体，军事根基、贵族利益与中原治理需求之间存在张力。制度变化并非单向的文化替代。','孝文帝迁都洛阳，随后推进服饰、语言、姓氏等多方面改革。迁都和具体改革令各有实施年代。','可以比较政治中心迁移怎样改变精英网络与文化表达；不宜把这一过程简化为某一民族整体在某年突然消失。','494年突出迁都节点；495年前后的具体规定另有时间。后世所谓“汉化”应拆成可观察的制度与社会实践。','wei')
event(581,'杨坚建立隋朝','大兴、长安地区','杨坚、北周静帝','政治与制度','北朝的长期整合已形成较强的军事和行政资源。杨坚在北周政治结构内取得权力，再通过禅让建立新朝。','杨坚建立隋，改元开皇。此时南方陈朝仍在，隋朝建立与南北统一不是同一件事。','对照六世纪教会史时，可以分别观察制度继承、政治合法性与宗教赞助；两地相似的皇权表达不能直接视为相互借鉴。','依据开皇元年纪事；隋灭陈的589年另列。电子古籍提供篇章入口，具体诏令仍需结合版本阅读。','sui1')
event(589,'隋灭陈与南北统一','建康、大兴','隋文帝、杨广、陈叔宝','政治与制度','南北分立时期并非完全隔绝，隋的军事推进和制度整合利用了长期积累的力量。南方地方社会有自己的历史。','隋军攻入建康，陈朝覆亡，南北长期分立告一段落。统一后的地方接收、人口登记与治理仍是持续过程。','与东罗马的战争和帝国整合并置，可以讨论统一的资源成本及宗教赞助，但不把两个帝国当作相同制度。','以开皇九年为政治节点；统一不等于所有边界固定，也不表示不同文化实践从此被完全消除。','sui')
event(605,'运河工程与帝国交通','洛阳、通济渠及相关水路','隋炀帝、征役民众','交通与交流','南北资源与政治中心的联系需要粮运和水路体系。既有河渠与新开工程共同形成后来所称的大运河网络。','隋炀帝时期展开通济渠等大规模工程，改善不同水系之间的连接，同时伴随沉重的征役和供给需求。','水运改变政治资源、贸易和人员流动，但工程的收益与承担劳役者的代价并不平均。不能只用伟大工程或暴政一个词代替分析。','605年突出一批工程；运河不同段落的形成跨越多个年代，并非一条河在一年内全部建成。','sui3')
event(618,'唐建立与秩序重建','长安','李渊、隋末各地势力','政治与制度','隋末动荡形成多个军事政治中心，李渊在关中取得基础。新朝既继承隋制，也面对持续的战争与地方谈判。','李渊建立唐朝。此后统一战争继续，不能将618年当作唐已控制后来全部疆域的年份。','对照地中海与西亚的七世纪变化，应注意各地区转折的不同节奏；同一世纪的帝国扩展不必有共同原因。','唐高祖李渊建国与唐太宗626年继位应分开；地图仍需按年份呈现控制范围变化。','timeline,tang')
event(626,'太宗继位与贞观政治的起点','长安','李世民、李建成、李元吉','政治与制度','唐初宗室间对军政资源和继承权的竞争加剧。太宗后来的治世形象也与史书编纂及政治记忆有关。','玄武门之变后，李世民成为太子，并继承皇位。贞观年号次年开始，不能与626年完全等同。','此例帮助区分政变、继位、改元与后世评价。比较帝国中的宗教许可时，也需追踪具体政策，而非只借“开明君主”的标签。','本纪提供政治编年；对人物动机及胜者如何塑造记忆，需比较多类材料，不只照录成功者自述。','tang')
event(629,'玄奘西行与求学网络','长安、中亚、印度','玄奘、沿途僧侣与统治者','交通与交流','佛教经典与解释传统在不同地区发展，求学者借助绿洲交通、寺院及地方政治关系远行。','玄奘约于629年出发，前往中亚与印度诸地求学，后来返回长安从事译经。行程包含长期停留而非连续直线旅行。','他与同世纪的东叙利亚语教会都体现跨语言宗教网络，但属于不同社群。地理接近并不自动证明具体会面或共同传播。','出发年份有627、629等讨论，本条采用常见629年并明确为约年；不将一条确定的公历日强加给所有行程。','xuanzang',645)
event(635,'阿罗本来华的碑文记忆','长安','阿罗本、唐太宗','教会与交流','东叙利亚语教会在西亚、中亚存在多种联系，唐代长安的政治与商旅环境为外来人员提供活动空间。','781年景教碑回顾阿罗本于贞观九年携经抵达长安，并叙述朝廷接待、翻译与考察教义的过程。','这是在华教会史的重要文献锚点。它不能证明中国所有地方同时出现教会，也不应归作现代某一宗派在唐代的直接组织延续。','635年由146年后的碑文保存，属于回顾记述。碑文的颂扬语言、译名与朝廷关系需作为文本特点分析。','stele')
event(638,'景教建寺许可的记述','长安','唐太宗、阿罗本','教会与交流','外来宗教在唐朝活动涉及翻译、户籍、寺院和政治许可。获得朝廷认可与地方实际生活是不同层次。','景教碑载贞观十二年诏许相关教导流行，并记在长安建寺等安排。碑文借政治认可来表达群体的正当性。','可以与罗马帝国的宗教法令比较文本如何赋予合法位置；不能因都有皇帝支持，就认为法律范围、社群规模和信仰内容一致。','保留“据碑记述”的证据性质；不把碑文中的概括词直接换算成全国范围的可量化成果。','stele')
event(645,'玄奘归国与长安译经','长安','玄奘、译场僧侣、唐太宗','文本与科技','长距离求学取得的梵文文本，需要转为汉语并进入已有佛教解释传统。翻译是集体组织和长期学术劳动。','玄奘返回长安后展开大规模译经，并整理西行见闻。译场包含口译、笔受、证义等不同工作。','这有助于理解同时期长安为何能成为多语言宗教活动中心；但佛教译场的制度不能未经证明便套用于景教译经。','归国、译经、旅行记编成是不同事件。以645年作归国节点，不表示所有译作都在该年完成。','xuanzang')
event(755,'安史之乱爆发','范阳、洛阳、长安','安禄山、唐玄宗、唐肃宗','战争与迁徙','唐的边镇军力、财政供给与朝廷政治关系存在长期张力。边疆扩展与宫廷政策共同构成战事背景。','安禄山起兵，战争迅速波及两京等地区。其后的军事动员与地方权力变化持续多年，唐朝并未在755年灭亡。','战争对寺院、商人、农民与不同宗教群体的影响不一。781年景教碑中的服务和忠诚语言也应放在战后政治环境中阅读。','以天宝十四载起兵为节点；战争结束和后续藩镇格局不能压成同一时刻。','tang9')
event(781,'景教碑立与双语群体记忆','长安','景净、伊斯、景教僧众','教会与交流','唐代景教群体需要向汉文读者表达其教义、人员网络与政治位置。碑刻既是纪念物，也是经过选择的公共叙述。','《大秦景教流行中国碑》立石，汉文与叙利亚文共同保存宗教表述、人员名单及此前传播的回顾。','碑文借儒释道及帝国政治词汇解释信仰，展现翻译选择。其存在是重要实物证据，却不能代替未被记下的地方和日常实践。','立碑年、所叙635与638年及近代发现史分开理解。不能将碑上的每个赞语都当作可直接统计的历史事实。','stele')
event(845,'会昌宗教政策与景教人员','长安及各地','唐武宗、佛教与外来宗教人员','宗教与思想','唐后期朝廷对寺院资源、户籍及政治秩序进行整顿。不同宗教的制度位置、社会资源与政策待遇并不相同。','会昌年间的宗教政策大规模冲击佛教寺院，并波及大秦、穆护等外来宗教人员，景教的公开机构受到影响。','国家命令和地方执行仍须分别考察。不能从一项诏令直接推出每个地方的信徒都立即消失，也不能无材料地填出完整延续谱系。','本条以845年政策高潮为节点。术语指涉与人数记载需结合史书、碑刻及地方材料参读。','tang18')
event(907,'唐亡与五代十国格局','中原、江南及各地','朱温、各地统治集团','政治与制度','唐末长期战争使地方军事与财政力量扩大。中央王朝的名义与地方控制范围已经分离。','朱温代唐建立后梁，北方进入五代相继更替的时期；南方等地多个政权并存，经济与文化发展并未统一停滞。','一张标注“后梁”的地图不能代表当时所有中国地区。对照欧洲地方权力与修院网络时，也应避免用单一王朝概括全部社会。','907年是王朝更替节点；“五代十国”是概括性分期，不是同时存在十五个固定不变政权的精确数量表。','timeline')
event(960,'赵匡胤建立宋朝','陈桥、开封','赵匡胤、后周恭帝','政治与制度','五代军事集团与皇位更替相连。后周留下的军政与财政基础，为宋初整合提供资源。','赵匡胤在陈桥兵变后建立宋朝，以开封为都。随后逐步征服部分割据政权，辽等政权仍与宋并存。','宋初加强中央控制的措施有长期过程，不能只用“杯酒释兵权”故事解释全部制度。与西欧封建关系比较时，应具体到财政、军队和官僚任用。','建隆元年为建国节点。宋太祖并未完成对所有南北地区的统一，后续疆界须逐年判断。','songhistory')
event(1005,'澶渊之盟与宋辽边境','澶州、宋辽边境','宋真宗、辽圣宗、萧太后','政治与制度','宋辽长期战争给双方带来军事和财政压力。战场、谈判与边境贸易共同塑造关系。','宋辽达成澶渊之盟，以岁币等安排维持双方关系。边境随后存在较长时间的相对稳定及贸易往来。','对照同世纪欧洲权威关系时，可以比较条约如何安排秩序；不能把岁币简单等同于国家完全臣服，也不把和平理解为完全无冲突。','事件跨农历景德元年与公历1005年初，常见1004、1005两种标年；本项目以达成盟约的公历1005年列出。','song6')
event(1040,'西夏建国后的宋夏战争阶段','西北边境','李元昊、宋仁宗','战争与迁徙','西夏于1038年建国后，宋与西夏关系紧张。边境军费、羁縻与地方社会共同承受冲突。','1040年前后宋夏发生重要战事，战争延续到议和。此条用作战争阶段入口，并不声称所有战役在1040年发生。','宋、辽、西夏的并存说明中国历史不能只沿宋的宫廷线索叙述。战争与贸易、谈判之间也并非只有非此即彼的选择。','约年阶段条目，具体战役与1044年议和各有年份；不将三者混为一件事件。','songlife,timeline',1044)
event(1069,'王安石参政与新法展开','开封及各地','王安石、宋神宗、司马光','政治与制度','宋的财政、边防与社会资源分配存在不同诊断。官员对国家应干预到何种程度有深刻分歧。','王安石任参知政事，新法陆续展开，涉及财政、役法、军事和学校等领域。不同法令出台及地方施行的时间并不相同。','可以与宗教改革比较论争和文本传播，却不能把改革者与反对者机械对应为相同宗派。政策目标、执行者和实际后果应分别讨论。','熙宁二年为新法展开的关键节点；不同史书及党争材料对成败的评价须交叉阅读，不将某一立场当作完整事实。','song15')
event(1088,'《梦溪笔谈》与知识记录','润州、梦溪园','沈括','文本与科技','宋代官员、工匠、医者与地方知识通过不同渠道流动。文人著作保存技术记载，也带有作者的观察范围。','沈括晚年整理《梦溪笔谈》，内容涉及天文、地理、工艺与见闻。书中关于毕昇活字的记述是重要材料。','可与欧洲印刷及知识分类比较，但应区分技术出现、实际使用规模和长期社会后果。不能从一段技术描述推出全国普及。','1088年为常用的约略成书节点，非所有条目写成的确切年份；毕昇活动记为庆历年间，不能说1088年才发明活字。','songlife',1095)
event(1127,'靖康之变与宋廷南渡','开封、江南','宋徽宗、宋钦宗、赵构','战争与迁徙','金崛起改变宋辽关系，宋金战争迅速影响中原与朝廷。军事失败、人口移动和财政转移相互关联。','金军攻破开封并俘徽、钦二帝等，赵构在南方重建宋廷。此后宋金分立，南宋逐渐以临安为政治中心。','南宋延续了许多制度，同时面对新的海运、边境与文化环境。不能将1127年写成宋朝全部灭亡，也不把北方居民排除于中国历史之外。','靖康事件、赵构即位、临安地位确立是连续但不同的节点；地点与年份不能一并压成1127年定都临安。','song23,timeline')
event(1141,'宋金和议与疆界安排','临安、宋金边境','宋高宗、秦桧、金熙宗','政治与制度','南宋与金长期交战，朝廷内部对战争、资源与议和意见分歧。边疆居民的处境不能只从宫廷谈判理解。','宋金在1141年前后达成绍兴和议，条约落实及相关政治事件延续到次年。双方以新的身份和疆界安排维持关系。','和议可与欧洲宗教政治协议比较其适用对象与限制，不能把制度差异抹平为单一的“投降”或“和平进步”标签。','1141为议和节点；岳飞之死在农历1141年末、对应公历1142年初，不在这里用模糊年份替代具体时间问题。','timeline,songlife',1142)
event(1175,'鹅湖之会与儒学论辩','信州鹅湖','朱熹、陆九渊、吕祖谦','宗教与思想','宋代士人通过书院、讲学、书信及著述讨论经典与修养。后来的学派划分不等于当事人每次讨论的全部立场。','朱熹、陆九渊等在鹅湖相会，对为学方法等问题展开讨论。这是理解宋学内部差异的一个节点。','与经院哲学或宗教改革比较时，可以讨论经典解释和教育方式；不能将理学直接称为基督教的对应宗派，也不据争论断言此后完全断交。','具体发言与学派形象经过后来的传记、语录和学术史塑造，应区分当时材料与后设分类。','zhuxi,songlife')
event(1206,'成吉思汗与蒙古政治整合','蒙古高原','铁木真','政治与制度','蒙古高原多个政治军事集团经历结盟和战争。新的组织机制与个人关系网络共同参与整合。','铁木真在政治集会上获成吉思汗称号，蒙古帝国的扩展进入新阶段。其后不同方向的征服跨越数十年。','蒙古扩张造成战争和巨大破坏，也改变欧亚人员流动。不能只用“丝路畅通”遮蔽暴力，也不能假定整个欧亚从此有单一制度。','1206年为政治整合标志，元朝国号要到1271年才出现；蒙古帝国与元朝不是完全同义词。','mongols,timeline')
event(1234,'金亡与北方政权变化','蔡州、北方地区','金哀宗、蒙古军、南宋军','战争与迁徙','蒙古对金长期作战，南宋也在特定条件下参与军事行动。各方的短期目标与长期处境不同。','金朝覆亡，北方权力格局进一步改变。宋蒙关系此后继续演变，并走向长期战争。','同一军事合作不能等同于永久同盟；对照欧洲联盟与战争，也需分析参与者的具体利益与资源。北方居民的政治身份与文化归属不是一条线。','以1234年金亡为节点；不能因此提前把南宋从地图上抹去，也不把蒙古在北方的治理简单等同于后来元朝制度。','mongols,timeline')
event(1271,'忽必烈定国号大元','大都','忽必烈','政治与制度','蒙古帝国内部存在继承与地域权力分化。忽必烈在统治中国地区的过程中，采用多种治理与合法性资源。','忽必烈宣布国号大元，新的王朝名称与既有蒙古统治结构并存。南宋仍在继续抵抗。','可以观察跨地区帝国如何同时运用不同政治语言；不能因为采用汉文国号，就把蒙古其他汗国全部当作元朝地方行政区。','至元八年对应1271年；忽必烈1260年即位、1271年建国号与1279年南宋覆亡是三件不同的事件。','yuan,mongols')
event(1279,'南宋覆亡与元的统治扩展','崖山、南方地区','陆秀夫、张世杰、元军','战争与迁徙','元军长期推进，南宋朝廷不断南移。战争改变城市、人口和地方权力关系。','崖山战役后南宋覆亡，元完成对南宋政治中心的征服。地方接收、秩序恢复与社会变动仍长期持续。','对照欧亚教会网络时，政治整合有助于理解通道与任命，却不能由帝国疆界推断所有地区使用相同宗教制度。','以政治政权终结为节点；普通人的生存、地方抵抗及文化延续不能因政权灭亡而从叙事中消失。','yuan10,mongols')
event(1287,'拉班扫马的欧洲使行','大都、中东至欧洲','拉班扫马、阿鲁浑','教会与交流','拉班扫马出身东方基督徒环境，西行后进入伊儿汗国的外交与教会网络。其路线并不是从西欧向中国的单向传播。','拉班扫马奉使前往欧洲，与不同教会和政治人物会面，为理解东方基督徒的跨区域活动提供重要线索。','这条故事纠正“所有交流都由西方传来”的单向视角。宗教身份、外交任务与语言翻译同时作用，不能归纳成简单的宗派联合。','拉班扫马的身世、旅程与欧洲会面依叙事文本及外交材料参读；本条1287突出欧洲使行，不把其一生压缩到这一年。','mongols')
event(1294,'孟高维诺在大都的活动节点','汗八里、大都','孟高维诺','教会与交流','元代存在不同基督徒传统，拉丁传教士依赖跨洲通道、地方支持和语言学习进入中国城市。','孟高维诺约于此年前后抵达大都并开展活动。其后书信提及儿童教育、礼仪及与其他基督徒的关系。','“基督徒”并不表示一个没有分歧的组织。需要同时辨认东方教会、拉丁传教士及各类地方支持者的不同位置。','1294为常见约年，抵达与具体工作需按书信等材料区分。1307年总主教任命另列，不当作到达之年。','mongols')
event(1307,'汗八里总主教任命','罗马、汗八里','孟高维诺、教宗克勉五世','教会与交流','远距离传教网络需要使者、书信和主教祝圣，信息往返可能经历多年。教廷任命与地方实际机构形成并不同步。','教宗任命孟高维诺为汗八里总主教，并安排其他主教前往。任命本身不能证明所有受派人员都顺利到达。','这一节点适合比较制度文书与实际执行之间的距离。地图上的连线只能表达联系，不是所有人员精确旅程的复原。','1307突出任命；抵达大都、写报告、获任和后来祝圣应分别查证，不合并成一次事件。','mongols')
event(1368,'明朝建立与元廷北退','南京、大都','朱元璋、元顺帝','政治与制度','元末战争涉及多股军事、宗教与地方势力。朱元璋取得江南财政和军事资源后推进建国。','朱元璋建立明朝；明军随后占领大都，元廷北退。政权更替不等于蒙古势力在所有地区立即终止。','对照欧洲晚期中世纪时，可以比较战争后的重建与国家财政；不应从一朝更替直接推断所有在华教会社群同时消失或持续。','1368为明建立与大都易手之年。元之后在北方的政治延续须与明的统一叙述区分。','ming1,timeline')
event(1405,'郑和首次下西洋','南京、东南亚与印度洋','郑和、航海人员、沿途统治者','交通与交流','明初海上交通既有朝贡外交，也有贸易和海域政治。船队运作依赖造船、补给、翻译与沿途港口。','郑和奉命首次下西洋，开启一系列航行。各次航程的目的地、接触与规模并不完全相同。','与欧洲海上扩展比较时，应具体比较政治目的、武力、商业组织与地方反应，不能只列谁先到哪里作为文明高低的判据。','1405为首次出发，不是所有航行的总年份；也不将后来的海禁政策理解成中国从此与海洋完全隔绝。','ming304')
event(1449,'土木之变与北京保卫','土木堡、北京','明英宗、于谦、也先','战争与迁徙','明与蒙古各部的关系包含战争、贸易和边境谈判。皇帝亲征及军事供给涉及多重决策。','明英宗在土木堡之变中被俘，随后北京防卫成为政治和军事焦点。帝位与被俘皇帝身份的处理也改变朝廷关系。','这一节点说明王朝不能只按文化成就线性叙述。与同时期欧洲战争并置时，仍需保留草原政治与明朝制度的具体环境。','以1449年危机为节点；皇帝获释、复辟和后续边境政策是不同事件，不放进同一年。','timeline,ming')
event(1517,'葡萄牙使团抵达广州','广州、澳门及海上通道','皮莱资、葡萄牙使团、明朝官员','交通与交流','印度洋与东亚海上贸易连接多个政治体系，葡萄牙人通过航线和据点尝试进入既有贸易网络。','葡萄牙使团到达广州并寻求与明朝建立正式关系；后续赴北京、交涉受挫及冲突各有具体年代。','1517也常用作欧洲宗教改革的标志年。两件事可并列，但尚不能因此说路德改革直接造成此次使行或中国立即回应了改革。','这里选择抵达广州的1517年，不将后来在澳门的定居、耶稣会来华和此使团混为一次事件。','ming,timeline')
event(1572,'万历即位与张居正执政','北京及各地','万历帝、张居正','政治与制度','明代财政、边防和官僚考核存在长期议题。幼年皇帝继位使内阁、宫廷和行政协作尤为重要。','万历帝即位，张居正主持政务，推进考成、清丈及财政调整等措施；不同政策并非全部在1572年同步实施。','与欧洲改革并置时，可关注印刷、财政和教育，但不把官僚改革直接解释成基督教改革的对应物。制度目标与合法性语言不同。','以继位和政治阶段开端为节点；“一条鞭法”有较长形成过程，不应说由张居正在这一年单独从零发明。','ming213')
event(1582,'利玛窦抵达澳门','澳门','利玛窦、罗明坚','教会与交流','澳门的海上贸易与葡萄牙网络，为欧洲传教士学习语言、收集信息和寻求进入内地提供环境。','利玛窦抵达澳门，随后参与进入广东的准备。进入内地需要地方官许可和持续的语言、礼俗学习。','可将海上网络与元代陆路联系比较，注意二者的交通、帝国结构和社群条件不同；也不把澳门等同于整个中国的宗教处境。','1582是抵澳节点，1583肇庆居留与1601进北京另列。“来华”在不同文本中可能按不同地点起算。','ricci')
event(1583,'肇庆居留与中文交往','肇庆','利玛窦、罗明坚、地方官与士人','教会与交流','从澳门进入内地，需要在地方治理、户籍与宗教分类中取得可容纳的位置。服饰与身份表达也会变化。','利玛窦、罗明坚获准在肇庆居留，学习中文并展示地图等物品，与官员和士人建立关系。','地方许可不等于全国自由传教。可以追踪交往如何通过具体人际关系展开，而不是把“西学东渐”当作没有参与者的抽象过程。','以1583年居留为节点；初期以僧人身份表达和后来儒士式形象不同，不把后者提前套回最初阶段。','ricci')
event(1601,'利玛窦进入北京','北京','利玛窦、万历帝、宫廷官员','教会与交流','长期旅行、引荐与礼物交涉，使传教士逐步进入中央政治空间。宫廷态度与地方官员的理解并不一致。','利玛窦获准进入并居留北京，建立新的士人和宫廷联系。此事扩大其活动空间，但不等于他与皇帝有直接长谈。','可以比较唐代景教碑的朝廷许可与晚明具体交往；相隔近千年的政治语言、文献与宗教分类已有很大变化。','1601突出进入北京及获准居留，不把后来的受洗人数或全部译著算作该年的成果。','ricci')
event(1602,'《坤舆万国全图》刊行','北京','利玛窦、李之藻、刻印者与读者','文本与科技','中文地图传统与欧洲地图学相遇，需要翻译地名、解释球形世界并选择读者熟悉的表达方式。','《坤舆万国全图》在北京刊行，结合地图、说明文字和新的地理知识。不同版本与后来的摹本需要分别辨认。','这是一件可以直接观察版面和文字的实物。地图呈现新的空间秩序，却不等于所有读者立即接受同一世界观或基督信仰。','以国会图书馆藏1602年版为资料入口。地图来源与当事人的解释可以核对，但社会接受仍需书信、日记和地方材料。','ricci')
event(1607,'《几何原本》前六卷刊行','北京','徐光启、利玛窦','文本与科技','数学知识跨语言转译，要求处理术语、定义与证明顺序。合作者的语言能力与学术目标各有作用。','徐光启与利玛窦合作译刊《几何原本》前六卷，借助所用欧洲版本的解释传统，形成重要的中文数学文本。','可以比较宗教文本和科学文本的翻译，但二者的权威、验证方式及读者并不相同。合作不意味着所有政治与礼仪判断一致。','1607只包括前六卷，不写成全部十三卷已经译成；后九卷在十九世纪另由其他译者完成。','ming255,ricci')
event(1616,'南京教案与传教处境变化','南京、北京、澳门','沈㴶、传教士与中国信徒','教会与交流','晚明对传教士的评价既受地方纠纷，也受礼仪、行政秩序与政治怀疑影响。中国信徒并非被动接受者。','南京发生针对传教活动的查禁与争议，一些传教士被拘押或遣返，相关辩护通过奏疏和文字展开。','这反映同一国家内部政策与地方关系的差异。不能用有宫廷支持来推定各地安全，也不把反对者的全部理由归为单一排外。','1616为南京教案；1664年的历狱属于清初另一事件，超过本项目终点，不能混称为同一次。','ming255')
event(1629,'历法改革与中西合作','北京','徐光启、李天经、耶稣会士','文本与科技','天象预测与历法关系国家礼仪、行政和政治合法性。不同方法需要借具体计算、观测和制度支持进行比较。','朝廷展开历法改革，徐光启等与耶稣会士组织译算、观测及编纂，逐步形成《崇祯历书》相关成果。','译书、观测、官署组织和国家采用是不同环节。不能把科学合作简单写成全社会皈依，或说欧洲知识在没有本地参与的情况下自行传播。','1629是历局工作的关键开端；书稿编成、新政权采用及1645年施行分别列年。','ming255')
event(1637,'《天工开物》与生产知识','江西及多地','宋应星、工匠与生产者','文本与科技','明代生产技术依地方经验、市场和工匠实践发展。文人整理生产知识时，会选择自己所见与所得信息。','宋应星刊行《天工开物》，记录农业、纺织、冶金等技术。它提供观察劳动和物质生产的另一类文本。','与晚明西学译著并读，可避免把中国知识史缩成传教士带来的知识；同时注意作者概述不等于所有地区都使用同一工艺。','1637为初刊年；条目中的技术往往早已实践，不能把书的出版年当作技术发明年。','ming')
event(1644,'北京易手与明清政权转折','北京、山海关、江南','崇祯帝、李自成、吴三桂、多尔衮','战争与迁徙','明末长期战争、财政困境和地方社会变化共同削弱朝廷。不同军事集团在此后仍持续争夺广大地区。','北京被李自成军占领，崇祯帝死；随后清军进入山海关并取得北京。南明等政权与各地抵抗仍继续。','不能把1644年画成全境在同一天完成改朝换代。宗教、历法、士人出处与地方生存，都在持续战争中面临不同选择。','1644为多个政治事件的关键年份，不将后续征服与1664历狱提前发生。对照1648欧洲和约时，也需说明中国战争仍在延续。','ming24,timeline')
event(1645,'新历施行与礼仪问题','北京、罗马及在华教会网络','汤若望、清廷、不同修会人员','教会与交流','历法合作跨越明清政权更替；在华礼仪实践的争论也通过远距离报告进入教廷决策。两条线索有关联但并非同一事件。','清廷开始施行新的历法安排；同年罗马有关中国礼仪的决定体现不同修会理解的分歧。需要分别阅读国家制度和教会文件。','国家采用历法不等于全面接受基督宗教；教廷文件也不自动说明每个地方如何执行。科学合作与礼仪争议应该并排而分别说明。','历法呈进突出1644年，实施突出1645年。礼仪决定的具体问题和后续变化需查原文，不能将后来争论的全部结局压入1645年。','ming255')
src('diamond','大英图书馆：《金刚经》','https://idp.bl.uk/discover/learning/dunhuang/collection-items/cave-17-the-library-cave/','868年有明确题记的雕版印本','馆藏实物与说明')
src('han67','《后汉书》党锢列传',W+'後漢書/卷67','李膺等及延熹九年党锢')
